import { useEffect } from 'react'
import { ArrowLeft } from 'lucide-react'
import { useCatalog } from '../lib/catalog-context'
import { SeriesCard } from '../components/SeriesCard'
import { navigate } from '../lib/router'
import { formatViews, chapterCountOf, slugify, seriesHref } from '../lib/utils'
import { setSeo, buildAuthorMeta } from '../lib/seo'

/**
 * /author/{slug} — every series by one author. Part of the programmatic
 * SEO surface (authors are plain text on series pages; here they become
 * crawlable hub pages). Mirrored by the prerenderer's author pages.
 */
export default function AuthorPage({ slug }: { slug: string }) {
  const { series: catalog, loading } = useCatalog()

  const author = catalog.find((s) => s.author && slugify(s.author) === slug)?.author
  const list = catalog
    .filter((s) => s.author && slugify(s.author) === slug)
    .sort((a, b) => b.views - a.views)

  useEffect(() => {
    // works list powers the ProfilePage/Person schema (mirrors prerender)
    if (author)
      setSeo(
        buildAuthorMeta(
          author,
          list.length,
          list.slice(0, 25).map((s) => ({ title: s.title, href: seriesHref(s) })),
        ),
      )
  }, [author, list.length])

  if (!loading && !author) {
    return (
      <main className="mx-auto max-w-[1240px] px-4 py-24 text-center sm:px-6 lg:px-8">
        <h1 className="text-2xl font-extrabold">Author not found</h1>
        <p className="mt-2 text-ink-soft">No manhwa or manhua on MANHWAS matches this author.</p>
        <button
          onClick={() => navigate('/directory')}
          className="mt-6 rounded-full bg-accent px-5 py-2.5 text-sm font-bold text-white"
        >
          Browse the directory
        </button>
      </main>
    )
  }

  const totalChapters = list.reduce((n, s) => n + chapterCountOf(s), 0)

  return (
    <main className="animate-fade-up">
      <div
        className="border-b border-line"
        style={{ background: 'linear-gradient(115deg, hsl(20 30% 14%) 0%, hsl(30 28% 26%) 100%)' }}
      >
        <div className="mx-auto max-w-[1240px] px-4 py-12 text-paper sm:px-6 lg:px-8">
          <button
            onClick={() => navigate('/directory')}
            className="mb-6 inline-flex items-center gap-1.5 text-sm font-semibold text-white/70 transition-colors hover:text-white"
          >
            <ArrowLeft width={16} height={16} /> Directory
          </button>
          <div className="eyebrow text-accent">Author</div>
          <h1 className="mt-2 text-4xl font-extrabold tracking-tight sm:text-5xl">
            {author ?? '…'}
          </h1>
          <div className="mt-6 flex flex-wrap gap-x-6 gap-y-2 text-sm text-white/60">
            <span>
              <strong className="text-white">{loading ? '…' : list.length}</strong> series
            </span>
            <span>
              <strong className="text-white">{loading ? '…' : formatViews(totalChapters)}</strong>{' '}
              chapters
            </span>
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-[1240px] px-4 py-10 sm:px-6 lg:px-8">
        <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
          {list.map((s) => (
            <SeriesCard key={s.id} series={s} />
          ))}
        </div>
      </div>
    </main>
  )
}
